// ============================================================================
// Repair Completion Flow
//
// Coordinates the four aggregates (Repair, Sale, Payment, Stock) to complete
// a repair by collecting payment, deducting stock for parts used, creating a
// linked Sale record with sourceType='repair', and marking the repair as completed.
//
// This is an all-or-nothing flow: if any step fails (stock check, sequence
// generation, DB insert), everything rolls back via SQLite transaction rollback.
// ============================================================================

import crypto from 'crypto'
import type Database from 'better-sqlite3'
import { db, sqliteDb } from '@/db/index.js'
import {
  customers,
  bicycles,
  repairs,
  repairLineItems,
  sequences,
} from '@/db/schema.js'
import { eq } from 'drizzle-orm'

// Completion flow imports — errors, types, and internal ports
import { RepairNotReadyError, PaymentMismatchError, InsufficientStockForRepairError } from './completion.errors.js'
import type { CompleteRepairResult, CompleteRepairPaymentInput } from './completion.types.js'
import { computeRepairTotals } from './pricing.js'
import { validateRepairStockAvailability } from './stock.js'

// RepairNotFoundError stays in repair.service.ts (shared with lifecycle functions)
import { RepairNotFoundError } from '../repair.service.js'

// ============================================================================
// Raw SQL executor — avoids Drizzle Date/number conversion issues with timestamps
//
// This is a local helper scoped to the completion flow. The top-level `run()`
// in repair.service.ts serves other sub-domains (lifecycle, line-items, etc.).
// Keeping it here reflects actual usage and avoids forcing unrelated functions
// to depend on this module's transaction pattern.
// ============================================================================

function run(sqlStr: string, params?: unknown[]): void {
  const client = sqliteDb as Database.Database
  client.prepare(sqlStr).run(...(params ?? []))
}

// ============================================================================
// Repository helpers — local queries needed by the completion flow
// ============================================================================

async function findRepairById(id: string): Promise<typeof repairs.$inferSelect | undefined> {
  const [result] = await db.select().from(repairs).where(eq(repairs.id, id))
  return result ?? undefined
}

async function findLineItemsByRepairId(repairId: string): Promise<typeof repairLineItems.$inferSelect[]> {
  return db.select().from(repairLineItems).where(eq(repairLineItems.repairId, repairId))
}

/** Record a status transition in the audit trail using raw SQL. */
async function recordStatusTransition(repairId: string, status: string): Promise<void> {
  const now = Date.now()
  run(
    'INSERT INTO repair_status_history (id, repair_id, status, transitioned_at) VALUES (?, ?, ?, ?)',
    [crypto.randomUUID(), repairId, status, now]
  )
}

// ============================================================================
// Cross-aggregate seam — linked Sale creation
//
// This function isolates the direct DB insert that creates the linked Sale record.
// The default is a direct call (current round), but this seam makes it possible to
// swap in a domain-event-driven version later without rewriting the rest of the flow.
// ============================================================================

/**
 * Create a linked Sale record and its line items for a completed repair.
 *
 * This is a private seam — callers pass the computed totals so that pricing
 * logic stays in the `pricing.ts` port and is not duplicated here.
 */
async function createLinkedSale(
  repairId: string,
  customerId: string | null,
  lineItems: typeof repairLineItems.$inferSelect[],
  subtotalNet: number,
  vatTotal: number,
  totalGross: number,
): Promise<{ saleId: string; saleNumber: string }> {
  // Get sale number from sequence table (increment)
  const updateResult = await db
    .update(sequences)
    .set({ currentValue: sql`${sequences.currentValue} + 1` })
    .where(eq(sequences.name, 'sale'))

  if (updateResult.changes === 0) {
    await db.insert(sequences).values({ name: 'sale', currentValue: 1 })
  }

  const [seqRow] = await db
    .select({ currentValue: sequences.currentValue })
    .from(sequences)
    .where(eq(sequences.name, 'sale'))
  const saleNumberSeq = seqRow!.currentValue
  const saleNumber = `SA-${String(saleNumberSeq).padStart(4, '0')}`

  const saleId = crypto.randomUUID()
  const now = Date.now()

  // Insert sale header with sourceType='repair'
  run(
    'INSERT INTO sales (id, sale_number, customer_id, source_type, source_id, status, subtotal_net, vat_total, total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [saleId, saleNumber, customerId, 'repair', repairId, 'completed', subtotalNet, vatTotal, totalGross, now]
  )

  // Insert sale line items (copy from repair line items)
  for (const li of lineItems) {
    const saleLineItemId = crypto.randomUUID()
    run(
      `INSERT INTO sale_line_items (id, sale_id, line_type, part_id, labor_service_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        saleLineItemId,
        saleId,
        li.lineType,
        li.partId,
        li.laborServiceId,
        li.description,
        Number(li.quantity),
        Number(li.unitPriceNet),
        li.vatRateId,
        li.discountPercent,
        Number(li.lineTotalNet),
        Number(li.lineTotalVat),
        Number(li.lineTotalGross),
        now,
      ]
    )
  }

  return { saleId, saleNumber }
}

// Need sql template tag for the sequence increment above
import { sql } from 'drizzle-orm'

// ============================================================================
// Public API — Complete Repair Payment (completion flow)
// ============================================================================

/**
 * Complete a repair by collecting payment, deducting stock for parts used,
 * creating a linked Sale record with sourceType='repair', and marking the
 * repair as completed.
 *
 * This is an all-or-nothing completion flow: if any step fails (stock check,
 * sequence generation, DB insert), everything rolls back via SQLite transaction.
 *
 * Flow:
 * 1. Validate repair exists and is in 'ready' status
 * 2. Compute total from line items (pricing port)
 * 3. Validate payment amounts match the computed total
 * 4. Check stock availability for all parts used (stock port)
 * 5. Transaction: create sale → create sale line items → create payments →
 *    create payment allocations → deduct stock via movements → mark repair completed
 *
 * @param id - Repair identifier (must be in 'ready' status)
 * @param input - Payment data (single or split methods)
 * @returns CompleteRepairResult with created entities
 */
export async function completeRepairPayment(
  id: string,
  input: CompleteRepairPaymentInput,
): Promise<CompleteRepairResult> {
  const validated = { payments: input.payments }

  if (validated.payments.length === 0) {
    throw new Error('At least one payment method is required')
  }

  // Step 1: Look up current repair state and validate it's in 'ready' status
  const current = await findRepairById(id)
  if (!current) {
    throw new RepairNotFoundError(id)
  }
  if (current.status !== 'ready') {
    throw new RepairNotReadyError(current.status as string)
  }

  // Resolve customerId from repair → bicycle → customer
  const [bicycle] = await db.select().from(bicycles).where(eq(bicycles.id, current.bicycleId))
  let saleCustomerId: string | null = null
  if (bicycle?.customerId) {
    const [cust] = await db.select().from(customers).where(eq(customers.id, bicycle.customerId))
    saleCustomerId = cust?.id ?? null
  }

  // Step 2: Fetch all line items and compute the expected total gross (pricing port)
  const lineItems = await findLineItemsByRepairId(id)
  if (lineItems.length === 0) {
    throw new Error('Cannot complete a repair with no line items')
  }

  const pricing = computeRepairTotals(lineItems)

  // Step 3: Validate payment total matches expected gross total
  const paidTotal = validated.payments.reduce((sum, p) => sum + p.amount, 0)
  if (paidTotal !== pricing.totalGross) {
    throw new PaymentMismatchError(pricing.totalGross, paidTotal)
  }

  // Step 4: Aggregate stock requests from part line items only
  const partLineItems = lineItems.filter(li => li.lineType === 'part')
  const stockRequests = partLineItems.map(li => ({
    partId: li.partId!,
    requestedQuantity: Number(li.quantity),
  }))

  // Step 5: Validate stock availability (stock port)
  const stockResult = await validateRepairStockAvailability(stockRequests)
  if (!stockResult.valid) {
    throw new InsufficientStockForRepairError(stockResult.shortfalls)
  }

  // Step 6: Execute completion transaction — all inserts or nothing
  const now = Date.now()

  // Declare variables before the try block so they're accessible in the return statement
  let saleId: string
  let saleNumber: string
  const createdPayments: Array<{ id: string; method: 'cash' | 'card' | 'bank_transfer'; amount: number }> = []
  const createdMovements: Array<{ id: string; partId: string; quantityDelta: number; reason: string; referenceType: string; referenceId: string }> = []

  try {
    // Begin transaction
    run('BEGIN TRANSACTION')

    // Create linked sale (cross-aggregate seam)
    ;({ saleId, saleNumber } = await createLinkedSale(
      id,
      saleCustomerId,
      lineItems,
      pricing.subtotalNet,
      pricing.vatTotal,
      pricing.totalGross,
    ))

    // Insert payment records and allocations for each payment method
    for (const pay of validated.payments) {
      const paymentId = crypto.randomUUID()
      run(
        'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
        [paymentId, pay.method, pay.amount, now]
      )

      // Insert payment allocation → sale
      run(
        'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
        [crypto.randomUUID(), paymentId, 'sale', saleId, pay.amount]
      )

      createdPayments.push({ id: paymentId, method: pay.method as 'cash' | 'card' | 'bank_transfer', amount: pay.amount })
    }

    // Insert stock movements (negative deltas for parts used)
    for (const li of partLineItems) {
      const movementId = crypto.randomUUID()
      run(
        'INSERT INTO stock_movements (id, part_id, quantity_delta, reason, reference_type, reference_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
        [movementId, li.partId!, -Number(li.quantity), 'repair_use', 'sale', saleId, now]
      )

      createdMovements.push({
        id: movementId,
        partId: li.partId!,
        quantityDelta: -Number(li.quantity),
        reason: 'repair_use',
        referenceType: 'sale',
        referenceId: saleId,
      })
    }

    // Update repair status to completed with completedAt timestamp
    run(
      'UPDATE repairs SET status = ?, completed_at = ? WHERE id = ?',
      ['completed', now, id]
    )

    // Record the final status transition in audit trail
    await recordStatusTransition(id, 'completed')

    // Commit transaction
    run('COMMIT')
  } catch (err) {
    // Rollback on any error
    try { run('ROLLBACK') }
    catch {}
    throw err
  }

  // Step 7: Fetch and return the updated repair + created entities
  const [updatedRepair] = await db.select().from(repairs).where(eq(repairs.id, id))

  if (!updatedRepair) {
    throw new RepairNotFoundError(id)
  }

  return {
    repair: {
      id: updatedRepair.id,
      bicycleId: updatedRepair.bicycleId,
      assignedTo: updatedRepair.assignedTo,
      status: 'completed' as const,
      customerNotes: updatedRepair.customerNotes,
      internalNotes: updatedRepair.internalNotes,
      holdReason: null, // cleared on completion
      holdReasonNote: null,
      plannedDate: updatedRepair.plannedDate ?? null,
      pickupDate: updatedRepair.pickupDate ?? null,
      completedAt: now,
      createdAt: updatedRepair.createdAt,
    },
    sale: {
      id: saleId,
      saleNumber,
      customerId: saleCustomerId,
      sourceType: 'repair',
      sourceId: id,
      status: 'completed',
      subtotalNet: pricing.subtotalNet,
      vatTotal: pricing.vatTotal,
      totalGross: pricing.totalGross,
    },
    payments: createdPayments,
    stockMovements: createdMovements,
  }
}

// ============================================================================
// Types — repair payment completion flow
// ============================================================================

import type { RepairStatus, HoldReason } from '@shared/validations/repair.js'

/** Result returned after successful repair payment completion */
export interface CompleteRepairResult {
  /** The updated repair record with completedAt set */
  repair: {
    id: string
    bicycleId: string
    assignedTo: string | null
    status: RepairStatus
    customerNotes: string | null
    internalNotes: string | null
    holdReason: HoldReason | null
    holdReasonNote: string | null
    plannedDate: number | null
    pickupDate: number | null
    completedAt: number | null
    createdAt: number
  }
  /** The linked sale record created for revenue attribution */
  sale: {
    id: string
    saleNumber: string
    customerId: string | null
    sourceType: 'direct_sale' | 'repair' | 'customer_order' | 'backorder'
    sourceId: string | null
    status: 'completed' | 'voided'
    subtotalNet: number
    vatTotal: number
    totalGross: number
  }
  /** All payments created for this completion */
  payments: Array<{
    id: string
    method: 'cash' | 'card' | 'bank_transfer'
    amount: number
  }>
  /** Stock movements created for parts used */
  stockMovements: Array<{
    id: string
    partId: string
    quantityDelta: number
    reason: string
    referenceType: string
    referenceId: string
  }>
}

/** Input for completing a repair with payment data (single or split) */
export interface CompleteRepairPaymentInput {
  /** Array of payment methods — single entry for single-payment, multiple for split */
  payments: Array<{
    method: 'cash' | 'card'
    amount: number
  }>
}

// ============================================================================
// Error types — repair payment completion flow
// ============================================================================

/** Thrown when a repair is not in 'ready' status and cannot be completed. */
export class RepairNotReadyError extends Error {
  constructor(public readonly currentStatus: string) {
    super(`Repair must be in 'ready' status to complete, currently '${currentStatus}'`)
    this.name = 'RepairNotReadyError'
  }
}

/** Thrown when payment total does not match the repair line item totals. */
export class PaymentMismatchError extends Error {
  constructor(
    public readonly expected: number,
    public readonly received: number,
  ) {
    super(`Payment total mismatch: expected ${expected} cents, received ${received} cents`)
    this.name = 'PaymentMismatchError'
  }
}

/** Thrown when stock is insufficient for parts used in a repair. */
export class InsufficientStockForRepairError extends Error {
  constructor(public readonly shortfalls: Array<{ partId: string; requested: number; available: number }>) {
    super(`Insufficient stock for ${shortfalls.length} part(s) in repair`)
    this.name = 'InsufficientStockForRepairError'
  }
}

// ============================================================================
// Pricing port — computes line totals and VAT for repair completion
//
// This is an internal helper used by the completion flow. It is not exported
// from repair.service.ts and the route layer never imports it directly.
// ============================================================================

/** Breakdown of pricing computed from a list of repair line items. */
export interface PricingBreakdown {
  /** Sum of all line_total_net values (in cents) */
  subtotalNet: number
  /** Sum of all line_total_vat values (in cents) */
  vatTotal: number
  /** Sum of all line_total_gross values (in cents) — the expected payment total */
  totalGross: number
}

/**
 * Compute pricing totals from repair line items.
 *
 * Sums `lineTotalNet`, `lineTotalVat`, and `lineTotalGross` across all items.
 * These columns are already computed at insertion time, so this is a pure
 * aggregation — no VAT rate lookup or per-line calculation needed.
 */
export function computeRepairTotals(lineItems: Array<{
  lineTotalNet: number | string
  lineTotalVat: number | string
  lineTotalGross: number | string
}>): PricingBreakdown {
  let subtotalNet = 0
  let vatTotal = 0
  let totalGross = 0

  for (const item of lineItems) {
    subtotalNet += Number(item.lineTotalNet)
    vatTotal += Number(item.lineTotalVat)
    totalGross += Number(item.lineTotalGross)
  }

  return { subtotalNet, vatTotal, totalGross }
}

// ============================================================================
// Stock port — validates and deducts stock for repair completion
//
// This is an internal helper used by the completion flow. It is not exported
// from repair.service.ts and the route layer never imports it directly.
//
// NOTE: Currently only called from the repair completion module. If another
// feature (e.g., direct_sale) needs the same stock check, this should become
// a peer module shared between features.
// ============================================================================

import { db } from '@/db/index.js'
import { stockMovements } from '@/db/schema.js'
import { sql, inArray, sum } from 'drizzle-orm'

/** Input: one part with a requested quantity to validate. */
export interface RepairStockCheckRequest {
  /** Part ID to check availability for */
  partId: string
  /** Number of units the repair uses */
  requestedQuantity: number
}

/** One part that does not have enough stock in the context of a repair completion. */
export interface RepairShortfallDetail {
  /** The part ID with insufficient stock */
  partId: string
  /** How many units were requested by the repair line items */
  requested: number
  /** How many units are actually available (computed from movements) */
  available: number
}

/** Result of validating a batch of stock requests for repair completion. */
export interface RepairStockValidationResult {
  /** true if every part has sufficient stock; false otherwise */
  valid: boolean
  /** Non-empty only when valid is false — lists each short-falling part */
  shortfalls: RepairShortfallDetail[]
}

/**
 * Validate whether requested quantities are available in stock for repair completion.
 *
 * Computes available stock per part by summing `quantityDelta` from the
 * `stock_movements` table — never trusts denormalized `quantityOnHand`.
 */
export async function validateRepairStockAvailability(
  requests: RepairStockCheckRequest[]
): Promise<RepairStockValidationResult> {
  if (requests.length === 0) {
    return { valid: true, shortfalls: [] }
  }

  const partIds = [...new Set(requests.map(r => r.partId))]

  const aggregationQuery = db
    .select({
      partId: stockMovements.partId,
      totalDelta: sql<number>`COALESCE(${sum(stockMovements.quantityDelta)}, 0)`
    })
    .from(stockMovements)
    .where(inArray(stockMovements.partId, partIds))
    .groupBy(stockMovements.partId)

  const aggregationResults = await aggregationQuery

  const availableMap = new Map<string, number>()
  for (const row of aggregationResults) {
    availableMap.set(row.partId, Number(row.totalDelta))
  }

  const shortfalls: RepairShortfallDetail[] = []
  for (const req of requests) {
    const available = availableMap.get(req.partId) ?? 0
    if (req.requestedQuantity > available) {
      shortfalls.push({
        partId: req.partId,
        requested: req.requestedQuantity,
        available
      })
    }
  }

  shortfalls.sort((a, b) => a.partId.localeCompare(b.partId))

  return {
    valid: shortfalls.length === 0,
    shortfalls
  }
}

